import asyncio
from functools import partial
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

# 1. Plain function
def plain_dep(q: str = "default"):
    return q

def plain_dep_partial(q: str = "partial_val"):
    return q

# 2. Async function
async def async_dep(q: str = "default"):
    return q

async def async_dep_partial(q: str = "partial_val"):
    return q

# 3. Callable class
class ClassDep:
    def __call__(self, q: str = "default"):
        return q

class ClassDepPartial:
    def __init__(self, fixed_val: str):
        self.fixed_val = fixed_val
    def __call__(self, q: str = "default"):
        return f"{q}-{self.fixed_val}"

# We want to use partial to fix some arguments.
# For a class, partial(ClassDep, ...) would call the constructor.

# Let's define the dependencies using partial
plain_partial = partial(plain_dep, q="fixed_plain")
async_partial = partial(async_dep, q="fixed_async")
class_partial = partial(ClassDep, q="fixed_class") # This is wrong, ClassDep is not a function that takes q in __init__

# Correct way to use partial with a class that has __call__:
# If we want to fix an argument of the __call__ method, we need to instantiate it first.
class_dep_instance = ClassDep()
class_partial_call = partial(class_dep_instance, q="fixed_class")

@app.get("/plain")
def read_plain(dep = Depends(plain_partial)):
    return {"dep": dep}

@app.get("/async")
async def read_async(dep = Depends(async_partial)):
    return {"dep": dep}

@app.get("/class")
def read_class(dep = Depends(class_partial_call)):
    return {"dep": dep}

client = TestClient(app)

def test_plain_partial():
    response = client.get("/plain")
    assert response.status_code == 200
    assert response.json() == {"dep": "fixed_plain"}

def test_async_partial():
    response = client.get("/async")
    assert response.status_code == 200
    assert response.json() == {"dep": "fixed_async"}

def test_class_partial():
    response = client.get("/class")
    assert response.status_code == 200
    assert response.json() == {"dep": "fixed_class"}

if __name__ == "__main__":
    try:
        test_plain_partial()
        print("Plain partial passed")
        test_async_partial()
        print("Async partial passed")
        test_class_partial()
        print("Class partial passed")
        print("All passed!")
    except Exception as e:
        print(f"Failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
